package me.uc_hussein.ultrastpa.command;
import me.uc_hussein.ultrastpa.ULTRASTPAPlugin;import org.bukkit.command.*;import org.bukkit.entity.Player;
public final class SimpleCommand implements CommandExecutor {private final ULTRASTPAPlugin p;private final String action;public SimpleCommand(ULTRASTPAPlugin p,String action){this.p=p;this.action=action;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player pl)){p.messages().send(s,"player-only");return true;}switch(action){case"here"-> {if(a.length<1){p.messages().send(pl,"usage");return true;}var t=p.server().getPlayerExact(a[0]);if(t==null){p.messages().send(pl,"unknown-player","%player%",a[0]);return true;}p.sendTPAHere(pl,t);}case"accept"->p.accept(pl);case"deny"->p.deny(pl);case"cancel"-> {if(a.length>0){var t=p.server().getPlayerExact(a[0]);if(t==null){p.messages().send(pl,"unknown-player","%player%",a[0]);return true;}p.requests().cancelSender(pl,t);}else p.requests().cancelLatest(pl);} }return true;}}
